mapper.select:
SELECT REQUEST_ID,PROGRAM_ID,OBJECT_VERSION_NUMBER,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,
LAST_UPDATE_DATE,LAST_UPDATE_LOGIN,WRITE_OFF_ID,WRITE_OFF_TYPE,WRITE_OFF_DATE,CSH_TRANSACTION_ID,
CSH_WRITE_OFF_AMOUNT,SUBSEQUENT_CSH_TRX_ID,SUBSEQ_CSH_WRITE_OFF_AMOUNT,REVERSED_FLAG,
REVERSED_WRITE_OFF_ID,REVERSED_DATE,CASHFLOW_ID,CONTRACT_ID,TIMES,CF_ITEM,CF_TYPE,
DESCRIPTION,WRITE_OFF_DUE_AMOUNT,WRITE_OFF_PRINCIPAL,WRITE_OFF_INTEREST,IMPORT_FLAG,
PAYMENT_REQ_LINE_ID,PAYMENT_REQ_ID,repayment_id,write_off_doc_category,withdraw_cf_id,withdraw_id
FROM csh_write_off


        write_off_type = #{writeOffType}


        AND csh_transaction_id = #{cshTransactionId}


        AND cashflow_id = #{cashflowId}


        AND withdraw_id = #{withdrawId}


        AND cf_item = #{cfItem}


        AND reversed_flag = #{reversedFlag}


ORDER BY write_off_Id ASC

SELECT nvl(cwo.csh_write_off_amount, 0) AS writeOffDueAmount, -- 核销金额 cwo.write_off_date AS writeOffDate, -- 核销日期 ( SELECT scvb.meaning FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'CSH.WRITE_OFF_TYPE' AND scvb. VALUE = cwo.write_off_type ) AS writeOffType, -- 核销类型 cc.contract_number AS contractNumber, -- 合同编号 '' as approvalNumber, cc.contract_id AS contractId, cwo.times AS times, -- 期数 (SELECT bp_name FROM hls_bp_master WHERE bp_id = cc.tenant_id ) AS bpName, -- 承租人 cc.tenant_id AS bpId, (select hci.description from hls_cashflow_item hci where hci.cf_item=cwo.cf_item) as description, -- 性质 nvl(cwo.write_off_principal, 0) AS writeOffPrincipal, -- 本金 nvl(cwo.write_off_interest, 0) AS writeOffInterest, -- 利息 cwo.LAST_UPDATE_DATE, -- 操作时间 cwo.import_flag, ( SELECT sys.description FROM sys_user sys WHERE sys.USER_ID = cwo.CREATED_BY ) AS userName FROM csh_write_off cwo LEFT JOIN con_contract_cashflow cashflow ON cwo.cashflow_id = cashflow.cashflow_id LEFT JOIN con_contract cc ON cc.contract_id = cwo.contract_id
cwo.write_off_id=#{writeOffId}
and cc.document_category=#{writeOffDocCategory}
UNION SELECT nvl(cwo.csh_write_off_amount, 0) AS writeOffDueAmount, -- 核销金额 cwo.write_off_date AS writeOffDate, -- 核销日期 ( SELECT scvb.meaning FROM sys_code_value_b scvb, sys_code_b scb WHERE scvb.CODE_ID = scb.CODE_ID AND scb. CODE = 'CSH.WRITE_OFF_TYPE' AND scvb. VALUE = cwo.write_off_type ) AS writeOffType, -- 核销类型 cc.contract_number AS contractNumber, -- 合同编号 fp.APPROVAL_NUMBER as approvalNumber, cc.contract_id AS contractId, cwo.times AS times, -- 期数 case when cashflow.cf_item=54 then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.principal_repayment_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) when cashflow.cf_item=51 then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.repay_guarantee_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( case fp.fund_restream_method when 'DIRECT' then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='SELLER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='BUYER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) end) end bpName,
-- 承租人 case when cashflow.cf_item=54 then ( select max(hbm.bp_id) from fct_project_bp fpb , hls_bp_master hbm where fpb.principal_repayment_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) when cashflow.cf_item=51 then ( select max(hbm.bp_id) from fct_project_bp fpb , hls_bp_master hbm where fpb.repay_guarantee_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( case fp.fund_restream_method when 'DIRECT' then ( select max(hbm.bp_id) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='SELLER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( select max(hbm.bp_id) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='BUYER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) end) end bpId,
(select hci.description from hls_cashflow_item hci where hci.cf_item=cwo.cf_item) as description, -- 性质 nvl(cwo.write_off_principal, 0) AS writeOffPrincipal, -- 本金 nvl(cwo.write_off_interest, 0) AS writeOffInterest, -- 利息 cwo.LAST_UPDATE_DATE, -- 操作时间 cwo.import_flag, ( SELECT sys.description FROM sys_user sys WHERE sys.USER_ID = cwo.CREATED_BY ) AS userName FROM csh_write_off cwo LEFT JOIN fct_quotation_cashflow cashflow ON cwo.cashflow_id = cashflow.quotation_cashflow_id LEFT JOIN fct_contract cc ON cc.contract_id = cwo.contract_id LEFT JOIN fct_project fp ON fp.project_id=cc.project_id
cwo.write_off_id=#{writeOffId}
and cc.document_category=#{writeOffDocCategory}

select t1.* from (SELECT t.*, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb where cv.CODE = 'CSH301_WRITE_OFF_TYPE' AND cv.code_id = cvb.code_id AND cvb.VALUE = t.write_off_type)write_off_type_n, (SELECT ct.transaction_date FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_date, (SELECT ct.transaction_type FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_type, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb, csh_transaction ct WHERE cv.CODE = 'CSH301_TRANSACTION_TYPE' AND cv.code_id = cvb.code_id AND cvb. VALUE = ct.transaction_type AND ct.transaction_id = t.csh_transaction_id) transaction_type_n, (SELECT ccc.due_date FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.CASHFLOW_ID) due_date, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = t.cf_item and i.cf_type = t.cf_type) cf_item_n, ((SELECT nvl(ccc.due_amount, 0) FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.cashflow_id) - (SELECT SUM(nvl(csh.csh_write_off_amount, 0)) FROM csh_write_off csh WHERE csh.cashflow_id = t.cashflow_id AND csh.reversed_flag = 'N')) unwrite_off_amount, (select cc.contract_number from con_contract cc where cc.contract_id = t.contract_id)contract_number, (select cc.contract_name from con_contract cc where cc.contract_id = t.contract_id)contract_name, (select bp.bp_name from hls_bp_master bp ,con_contract cc where bp.bp_id = cc.tenant_id and cc.contract_id = t.contract_id)tenant_name, (select u.description from sys_user u where u.user_id = t.created_by)write_off_by_n, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb WHERE cv.CODE = 'HLS_REVERSED_FLAG' AND cv.code_id = cvb.code_id AND cvb. VALUE = t.REVERSED_FLAG) reversed_flag_n, (select q.quotation_id from con_contract_cashflow ccc,prj_quotation q where ccc.cashflow_id = t.cashflow_id and ccc.generated_source = 'PRJ_QUOTATION' and ccc.generated_source_doc_id = q.quotation_id)quotation_id, (select ts.write_off_flag from csh_transaction ts where t.csh_transaction_id=ts.transaction_id) write_off_flag FROM csh_write_off t WHERE t.write_off_type != 'REFUND' )t1
1=1
and t1.csh_transaction_id =#{cshTransactionId}
and t1.reversed_flag = #{reversedFlag}
and ('Y'= #{nonRefundFlag} )
and ('Y'= #{refundFlag} AND t1.write_off_type = 'REFUND')
and t1.contract_number like #{contractNumber}
and t1.contract_name like #{contractName}
and t1.tenant_name like #{tenantName}
and t1.transaction_type = #{transactionType}

mapper.update:
update csh_write_off wo set
wo.subsequent_csh_trx_id = #{transactionId,jdbcType=BIGINT},
wo.subseq_csh_write_off_amount = #{transactionAmount,jdbcType=DOUBLE}
where
wo.write_off_id = #{writeOffId,jdbcType=BIGINT}

mapper.select:
SELECT
    cwo.*,
    ct.penalty_calc_date
FROM
    csh_write_off cwo,
    csh_transaction ct

    cwo.csh_transaction_id = ct.transaction_id
    and cwo.reversed_flag = 'N'

       and cwo.cashflow_id = #{cashflowId}


        and cwo.contract_id = #{contractId}


        and ct.penalty_calc_date = #{penaltyCalcDate}


        and cwo.cf_item = #{cfItem}


        and cwo.times = #{times}

SELECT cwo.*
  FROM csh_write_off cwo, con_contract_cashflow ccc

 cwo.cashflow_id = ccc.cashflow_id
 and ( ccc.cf_item = 0 or ccc.cf_item = 90 )
 and cwo.cashflow_id =#{cashflowId}
 and cwo.write_off_id = #{writeOffId}

SELECT cwo.*
  FROM csh_write_off cwo

       cwo.reversed_flag = 'N'
      and cwo.write_off_type =  'RECEIPT_CREDIT'
      and   cwo.contract_id = #{contractId}

      and   cwo.write_off_date   >   #{writeOffDateFrom}


       and   cwo.write_off_date  <=  #{writeOffDateTo}

select t1.* from (SELECT t.*, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb where cv.CODE = 'CSH301_WRITE_OFF_TYPE' AND cv.code_id = cvb.code_id AND cvb.VALUE = t.write_off_type)write_off_type_n, (SELECT ccc.due_amount from con_contract_cashflow ccc where ccc.cashflow_id = t.cashflow_id) due_amount, (SELECT ct.transaction_date FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_date, (SELECT ct.transaction_num FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_num, (SELECT ct.transaction_amount FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_amount, (SELECT ct.transaction_type FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_type, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb, csh_transaction ct WHERE cv.CODE = 'CSH301_TRANSACTION_TYPE' AND cv.code_id = cvb.code_id AND cvb. VALUE = ct.transaction_type AND ct.transaction_id = t.csh_transaction_id) transaction_type_n, (SELECT ccc.due_date FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.CASHFLOW_ID) due_date, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = t.cf_item and i.cf_type = t.cf_type) cf_item_n, ((SELECT nvl(ccc.due_amount, 0) FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.cashflow_id) - (SELECT SUM(nvl(csh.csh_write_off_amount, 0)) FROM csh_write_off csh WHERE csh.cashflow_id = t.cashflow_id AND csh.reversed_flag = 'N')) unwrite_off_amount, (select cc.contract_number from con_contract cc where cc.contract_id = t.contract_id)contract_number, (select cc.contract_name from con_contract cc where cc.contract_id = t.contract_id)contract_name, (select bp.bp_name from hls_bp_master bp ,con_contract cc where bp.bp_id = cc.tenant_id and cc.contract_id = t.contract_id)tenant_name, (select u.description from sys_user u where u.user_id = t.created_by)write_off_by_n, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb WHERE cv.CODE = 'HLS_REVERSED_FLAG' AND cv.code_id = cvb.code_id AND cvb. VALUE = t.REVERSED_FLAG) reversed_flag_n, (select q.quotation_id from con_contract_cashflow ccc,prj_quotation q where ccc.cashflow_id = t.cashflow_id and ccc.generated_source = 'PRJ_QUOTATION' and ccc.generated_source_doc_id = q.quotation_id)quotation_id FROM csh_write_off t)t1
1=1
and t1.cashflow_id = #{cashflowId}

select t1.* from (SELECT t.*, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb where cv.CODE = 'CSH301_WRITE_OFF_TYPE' AND cv.code_id = cvb.code_id AND cvb.VALUE = t.write_off_type)write_off_type_n, (SELECT ct.transaction_date FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_date, nvl((select wm_concat(car.allocation_id) from csh_allocation_receipt car where car.transaction_id = t.csh_transaction_id),-1) allocation_id_str, (SELECT ct.transaction_num FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_num, (SELECT ct.transaction_amount FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_amount, (SELECT ct.transaction_type FROM csh_transaction ct WHERE ct.transaction_id = t.csh_transaction_id) transaction_type, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb, csh_transaction ct WHERE cv.CODE = 'CSH301_TRANSACTION_TYPE' AND cv.code_id = cvb.code_id AND cvb. VALUE = ct.transaction_type AND ct.transaction_id = t.csh_transaction_id) transaction_type_n, (SELECT ccc.due_date FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.CASHFLOW_ID) due_date, (SELECT ccc.due_amount FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.CASHFLOW_ID) due_amount, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = t.cf_item and i.cf_type = t.cf_type) cf_item_n, ((SELECT nvl(ccc.due_amount, 0) FROM con_contract_cashflow ccc WHERE ccc.cashflow_id = t.cashflow_id) - (SELECT SUM(nvl(csh.csh_write_off_amount, 0)) FROM csh_write_off csh WHERE csh.cashflow_id = t.cashflow_id AND csh.reversed_flag = 'N')) unwrite_off_amount, (select cc.contract_number from con_contract cc where cc.contract_id = t.contract_id)contract_number, (select cc.contract_name from con_contract cc where cc.contract_id = t.contract_id)contract_name, (select bp.bp_name from hls_bp_master bp ,con_contract cc where bp.bp_id = cc.tenant_id and cc.contract_id = t.contract_id)tenant_name, (select u.description from sys_user u where u.user_id = t.created_by)write_off_by_n, (SELECT cvb.meaning FROM sys_code_b cv, sys_code_value_b cvb WHERE cv.CODE = 'HLS_REVERSED_FLAG' AND cv.code_id = cvb.code_id AND cvb. VALUE = t.REVERSED_FLAG) reversed_flag_n, (select q.quotation_id from con_contract_cashflow ccc,prj_quotation q where ccc.cashflow_id = t.cashflow_id and ccc.generated_source = 'PRJ_QUOTATION' and ccc.generated_source_doc_id = q.quotation_id)quotation_id FROM csh_write_off t)t1
t1.cf_item=9
and t1.contract_id = #{contractId}

select * from ( SELECT c.contract_number payment_number, p.project_number, p.contract_number, (SELECT t.company_full_name FROM fnd_company t WHERE t.company_id = p.company_spv) company_spv_n, c.contract_name, (SELECT bp_code FROM hls_bp_master WHERE bp_id = c.tenant_id) AS bp_code, (SELECT bp_name FROM hls_bp_master WHERE bp_id = c.tenant_id) AS bp_name, (SELECT s.description FROM sys_user s WHERE s.user_id = p.host_project_manager) host_project_manager_n, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.host_unit_id) host_unit_name, ct.transaction_num, ct.transaction_date, ct.transaction_amount, o.write_off_date, o.write_off_due_amount, o.write_off_principal, o.write_off_interest, o.cf_item, (SELECT h.description FROM hls_cashflow_item h WHERE h.cf_item = o.cf_item) cf_item_n, cc.due_date, nvl(cc.due_amount, 0) due_amount, nvl(cc.net_due_amount, 0) net_due_amount, nvl(cc.vat_due_amount, 0) vat_due_amount, nvl(cc.principal, 0) principal, nvl(cc.net_principal, 0) net_principal, nvl(cc.vat_principal, 0) vat_principal, nvl(cc.interest, 0) interest, nvl(cc.vat_interest, 0) vat_interest, nvl(cc.net_interest, 0) net_interest, o.reversed_flag, (select v.MEANING from sys_code_value_b_v v where v.CODE = 'HLS_REVERSED_FLAG' and v.code_value = o.reversed_flag)reversed_flag_n, o.reversed_date, o.description, nvl((SELECT wm_concat(car.allocation_id) FROM csh_allocation_receipt car WHERE car.transaction_id = ct.transaction_id), -1) AS allocation_id_str FROM csh_write_off o, con_contract c, prj_project p, csh_transaction ct, con_contract_cashflow cc WHERE o.contract_id = c.contract_id AND c.project_id = p.project_id AND o.csh_transaction_id = ct.transaction_id and cc.CF_DIRECTION = 'INFLOW' AND o.cashflow_id = cc.cashflow_id)t
1=1
and t.payment_number LIKE concat('%',concat(#{paymentNumber},'%') )
and t.project_number LIKE concat('%',concat(#{projectNumber},'%') )
and t.contract_number LIKE concat('%',concat(#{contractNumber},'%') )
and t.company_spv_n LIKE concat('%',concat(#{companySpvN},'%') )
and t.contract_name LIKE concat('%',concat(#{contractName},'%') )
and t.bp_code LIKE concat('%',concat(#{bpCode},'%') )
and t.bp_name LIKE concat('%',concat(#{bpName},'%') )
and t.host_project_manager_n LIKE concat('%',concat(#{hostProjectManagerN},'%') )
and t.host_unit_name LIKE concat('%',concat(#{hostUnitName},'%') )
and t.cf_item = #{cfItem}
and t.currency = #{currency}
and t.due_amount >= #{dueAmountFrom}
and t.due_amount <= #{dueAmountTo}
and t.write_off_due_amount >= #{writeOffDueAmountFrom}
and t.write_off_due_amount <= #{writeOffDueAmountTo}
and t.write_off_date >= #{writeOffDateFrom}
and t.write_off_date <= #{writeOffDateTo}
and t.reversed_flag = #{reversedFlag}
order by t.contract_number,t.write_off_date
